function validate([forest]) {
  if (!Array.isArray(forest) || forest.length < 1 || forest.length > 50) return 'forest needs 1 to 50 rows.';
  const n = Array.isArray(forest[0]) ? forest[0].length : 0;
  if (n < 1 || n > 50) return 'Each row needs 1 to 50 cells.';
  const heights = new Set();
  for (const line of forest) {
    if (!Array.isArray(line) || line.length !== n) return 'All rows must have the same length.';
    for (const h of line) {
      if (!Number.isInteger(h) || h < 0 || h > 1e9) return 'Each cell is an integer from 0 to 10^9.';
      if (h > 1) {
        if (heights.has(h)) return 'Tree heights must be distinct.';
        heights.add(h);
      }
    }
  }
  if (heights.size === 0) return 'The forest needs at least one tree (a value above 1).';
  if (forest[0][0] === 0) return 'The starting cell (0, 0) must not be 0.';
  return null;
}

