function cutOffTree(forest) {
  const rows = forest.length;
  const cols = forest[0].length;
  const trees = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (forest[r][c] > 1) {
        trees.push([forest[r][c], r, c]);
      }
    }
  }
  trees.sort((a, b) => a[0] - b[0]);
  const rowStep = [-1, 1, 0, 0];
  const colStep = [0, 0, -1, 1];
  const distance = (startRow, startCol, targetRow, targetCol) => {
    const dist = new Int32Array(rows * cols).fill(-1);
    const queueRows = [startRow];
    const queueCols = [startCol];
    dist[startRow * cols + startCol] = 0;
    for (let head = 0; head < queueRows.length; head++) {
      const r = queueRows[head];
      const c = queueCols[head];
      const here = dist[r * cols + c];
      if (r === targetRow && c === targetCol) return here;
      for (let d = 0; d < 4; d++) {
        const nr = r + rowStep[d];
        const nc = c + colStep[d];
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
        if (forest[nr][nc] === 0 || dist[nr * cols + nc] !== -1) continue;
        dist[nr * cols + nc] = here + 1;
        queueRows.push(nr);
        queueCols.push(nc);
      }
    }
    return -1;
  };
  let total = 0;
  let row = 0;
  let col = 0;
  for (const [, treeRow, treeCol] of trees) {
    const steps = distance(row, col, treeRow, treeCol);
    if (steps === -1) {
      return -1;
    }
    total += steps;
    row = treeRow;
    col = treeCol;
  }
  return total;
}

